    case ALMANAC_BUTTON:    if ( mExitCounter == 88 )  aSound = SOUND_ALMANAC;   break;
    case MAIL_BUTTON:       if ( mExitCounter == 88 )  aSound = SOUND_MAIL;      break;
    default: break;
